package social

const schema = `
CREATE TABLE profiles(user_id TEXT PRIMARY KEY REFERENCES host_users(id),handle TEXT UNIQUE NOT NULL,bio TEXT NOT NULL DEFAULT '',private INTEGER NOT NULL DEFAULT 0,links TEXT NOT NULL DEFAULT '[]',archive_stories INTEGER NOT NULL DEFAULT 1);
CREATE TABLE relations(actor TEXT NOT NULL,target TEXT NOT NULL,kind TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'accepted',PRIMARY KEY(actor,target,kind));
CREATE TABLE media(id TEXT PRIMARY KEY,owner TEXT NOT NULL,kind TEXT NOT NULL,original TEXT NOT NULL,rendered TEXT NOT NULL DEFAULT '',mime TEXT NOT NULL,sha TEXT NOT NULL,bytes INTEGER NOT NULL,state TEXT NOT NULL,created INTEGER NOT NULL,project TEXT NOT NULL DEFAULT '{}');
CREATE TABLE posts(id TEXT PRIMARY KEY,owner TEXT NOT NULL,kind TEXT NOT NULL,caption TEXT NOT NULL,alt TEXT NOT NULL DEFAULT '',location TEXT NOT NULL DEFAULT '',visibility TEXT NOT NULL,state TEXT NOT NULL,created INTEGER NOT NULL,publish_at INTEGER NOT NULL,expires INTEGER NOT NULL DEFAULT 0,media TEXT NOT NULL,extras TEXT NOT NULL DEFAULT '{}',request_key TEXT NOT NULL,UNIQUE(owner,request_key));
CREATE INDEX post_feed ON posts(state,publish_at DESC);
CREATE TABLE engagement(user_id TEXT NOT NULL,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,kind TEXT NOT NULL,collection TEXT NOT NULL DEFAULT '',PRIMARY KEY(user_id,post_id,kind));
CREATE TABLE comments(id TEXT PRIMARY KEY,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,owner TEXT NOT NULL,parent TEXT NOT NULL DEFAULT '',body TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE story_views(post_id TEXT NOT NULL,user_id TEXT NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(post_id,user_id));
CREATE TABLE story_votes(post_id TEXT NOT NULL,user_id TEXT NOT NULL,value TEXT NOT NULL,PRIMARY KEY(post_id,user_id));
CREATE TABLE highlights(id TEXT PRIMARY KEY,owner TEXT NOT NULL,title TEXT NOT NULL,posts TEXT NOT NULL);
CREATE TABLE drafts(id TEXT PRIMARY KEY,owner TEXT NOT NULL,document TEXT NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE events(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,actor TEXT NOT NULL,category TEXT NOT NULL,object TEXT NOT NULL,created INTEGER NOT NULL,seen INTEGER NOT NULL DEFAULT 0,delivered INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,next_attempt INTEGER NOT NULL DEFAULT 0,UNIQUE(user_id,actor,category,object));
CREATE TABLE preferences(user_id TEXT PRIMARY KEY,data TEXT NOT NULL);
CREATE TABLE push_subscriptions(id TEXT PRIMARY KEY,owner TEXT NOT NULL,data TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE reports(id TEXT PRIMARY KEY,owner TEXT NOT NULL,post_id TEXT NOT NULL,reason TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'open',created INTEGER NOT NULL);
CREATE TABLE jobs(id TEXT PRIMARY KEY,owner TEXT NOT NULL,media_id TEXT NOT NULL,edl TEXT NOT NULL,state TEXT NOT NULL,progress INTEGER NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL);
CREATE TABLE upload_intents(id TEXT PRIMARY KEY,owner TEXT NOT NULL,state TEXT NOT NULL,path TEXT NOT NULL,created INTEGER NOT NULL);
`
